import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const AdminPanel = () => {
  const { user } = useAuth(); // Keep this since it's used to check admin status
  const [activeTab, setActiveTab] = useState('dashboard');
  const [dashboardStats, setDashboardStats] = useState({});
  const [users, setUsers] = useState([]);
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        switch(activeTab) {
          case 'dashboard':
            const statsResponse = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/dashboard`, {
              headers: {
                'Authorization': `Bearer ${localStorage.getItem('token')}`
              }
            });
            const statsData = await statsResponse.json();
            setDashboardStats(statsData);
            break;

          case 'users':
            const usersResponse = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/users`, {
              headers: {
                'Authorization': `Bearer ${localStorage.getItem('token')}`
              }
            });
            const usersData = await usersResponse.json();
            setUsers(usersData.users || []);
            break;

          case 'items':
            const itemsResponse = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/items`, {
              headers: {
                'Authorization': `Bearer ${localStorage.getItem('token')}`
              }
            });
            const itemsData = await itemsResponse.json();
            setItems(itemsData || []);
            break;

          default:
            // Default case added to satisfy eslint
            break;
        }
      } catch (error) {
        console.error('Error fetching admin data:', error);
      } finally {
        setLoading(false);
      }
    };

    if (user?.isAdmin) {
      fetchData();
    } else {
      setLoading(false);
    }
  }, [activeTab, user]);

  if (!user?.isAdmin) {
    return (
      <div className="card">
        <h2>Access Denied</h2>
        <p>You do not have admin privileges to access this page.</p>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading admin panel...</p>
      </div>
    );
  }

  return (
    <div className="admin-panel">
      <div className="card">
        <div className="admin-tabs">
          <button 
            className={`tab-btn ${activeTab === 'dashboard' ? 'active' : ''}`}
            onClick={() => setActiveTab('dashboard')}
          >
            Dashboard
          </button>
          <button 
            className={`tab-btn ${activeTab === 'users' ? 'active' : ''}`}
            onClick={() => setActiveTab('users')}
          >
            Users
          </button>
          <button 
            className={`tab-btn ${activeTab === 'items' ? 'active' : ''}`}
            onClick={() => setActiveTab('items')}
          >
            Items
          </button>
        </div>

        {activeTab === 'dashboard' && (
          <div className="admin-tab-content">
            <h3>Dashboard Overview</h3>
            <div className="stats-grid">
              <div className="stat-card">
                <h4>Total Users</h4>
                <p className="stat-value">{dashboardStats.totalUsers || 0}</p>
              </div>
              <div className="stat-card">
                <h4>Total Items</h4>
                <p className="stat-value">{dashboardStats.totalItems || 0}</p>
              </div>
              <div className="stat-card">
                <h4>Total Games Played</h4>
                <p className="stat-value">{dashboardStats.totalGames || 0}</p>
              </div>
              <div className="stat-card">
                <h4>Total Volume</h4>
                <p className="stat-value">{dashboardStats.totalVolume || 0} AMP</p>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'users' && (
          <div className="admin-tab-content">
            <h3>Manage Users</h3>
            <div className="table-responsive">
              <table className="table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Username</th>
                    <th>Email</th>
                    <th>Balance</th>
                    <th>Role</th>
                    <th>Status</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {users.map((usr) => (
                    <tr key={usr.id}>
                      <td>{usr.id}</td>
                      <td>{usr.displayName}</td>
                      <td>{usr.email}</td>
                      <td>{usr.balance?.toLocaleString() || 0} AMP</td>
                      <td>{usr.isAdmin ? 'Admin' : 'User'}</td>
                      <td>
                        <span className={`badge badge-${usr.isActive ? 'success' : 'danger'}`}>
                          {usr.isActive ? 'Active' : 'Inactive'}
                        </span>
                      </td>
                      <td>
                        <button className="btn btn-sm btn-secondary">Edit</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'items' && (
          <div className="admin-tab-content">
            <h3>Manage Items</h3>
            <div className="table-responsive">
              <table className="table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Name</th>
                    <th>Description</th>
                    <th>Value</th>
                    <th>Rarity</th>
                    <th>Status</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {items.map((item) => (
                    <tr key={item.id}>
                      <td>{item.id}</td>
                      <td>{item.name}</td>
                      <td>{item.description}</td>
                      <td>{item.value?.toLocaleString() || 0} AMP</td>
                      <td>
                        <span className={`badge badge-${item.rarity}`}>
                          {item.rarity}
                        </span>
                      </td>
                      <td>
                        <span className={`badge badge-${item.isEnabled ? 'success' : 'danger'}`}>
                          {item.isEnabled ? 'Enabled' : 'Disabled'}
                        </span>
                      </td>
                      <td>
                        <button className="btn btn-sm btn-secondary">Edit</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminPanel;
